'use strict';
const solutions=[{label:"GENERAZIONE PROPRIA",title:"Più energia propria per l’autoconsumo.",text:"Confronta il profilo di generazione fotovoltaica con la domanda dell’azienda. Scopri quando puoi accumulare l’eccedenza e quando dovrai acquistare energia dalla rete.",task:"Coordinare generazione, domanda e disponibilità dell’accumulo.",logic:"Bilancio energetico unificato, previsione e piano di utilizzo degli asset disponibili.",audit:"Profilo di domanda, potenza fotovoltaica, limiti di immissione e disponibilità del BESS."},{label:"GESTIONE DELL’ACCUMULO",title:"La batteria segue la logica economica. Con la riserva necessaria.",text:"Sposta gli acquisti di energia tra le ore quando tariffa e condizioni tecniche lo rendono conveniente. Definisci separatamente la riserva di autonomia e l’utilizzo consentito della vita utile della batteria.",task:"Ridurre gli acquisti nelle ore costose conservando la riserva concordata.",logic:"Programma di carica e scarica che considera prezzo, rendimento, domanda e limiti.",audit:"Capacità utile, potenza, SoC, accesso al BMS e ai comandi dell’inverter."},{label:"MONITORAGGIO ENERGETICO",title:"Comprendi il sito attraverso i dati. In un quadro condiviso.",text:"Unisci i punti di consumo e generazione in una visione coerente. I dati condivisi aiutano l’energy manager a controllare le modalità operative e la direzione a capire la struttura dei costi.",task:"Unificare le letture disperse e comprendere il bilancio energetico.",logic:"Raccolta delle misure, storico, confronto dei periodi e analisi degli scostamenti.",audit:"Schema di misura, elenco dei contatori, interfacce e qualità dei dati disponibili."}];
const tabs=[...document.querySelectorAll('[data-solution]')];function selectSolution(i,focus=false){tabs.forEach((b,j)=>{b.setAttribute('aria-selected',String(i===j));b.tabIndex=i===j?0:-1});const s=solutions[i];for(const key of ['label','title','text','task','logic','audit'])document.getElementById('solution-'+key).textContent=s[key];document.getElementById('solution-content').setAttribute('aria-labelledby','tab-'+i);document.getElementById('solution-content').dataset.scenario=String(i);document.querySelector('.scenario-asset-map>span').textContent=["FV",'BESS',"Misure"][i];if(focus)tabs[i].focus()}tabs.forEach((b,i)=>{b.addEventListener('click',()=>selectSolution(i));b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();selectSolution(e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3,true)}})});selectSolution(0);
const menu=document.querySelector('.menu-toggle'),nav=document.getElementById('navigation');
const compactNavigation=window.matchMedia('(max-width:1020px)');
const menuOpenLabel=menu.getAttribute('aria-label');
const menuLinks=[...nav.querySelectorAll('a')];
function setMenuOpen(open,restoreFocus=false){
 const expanded=compactNavigation.matches&&open;
 nav.classList.toggle('open',expanded);
 menu.setAttribute('aria-expanded',String(expanded));
 menu.setAttribute('aria-label',expanded?"Chiudi il menu":menuOpenLabel);
 nav.inert=compactNavigation.matches&&!expanded;
 if(restoreFocus)menu.focus();
}
menu.addEventListener('click',event=>{
 const open=menu.getAttribute('aria-expanded')!=='true';
 setMenuOpen(open);
 if(open&&event.detail===0)menuLinks[0].focus();
});
menuLinks.forEach(link=>link.addEventListener('click',()=>{
 menuLinks.forEach(other=>other.removeAttribute('aria-current'));
 link.setAttribute('aria-current','location');
 setMenuOpen(false);
}));
document.addEventListener('click',event=>{
 if(menu.getAttribute('aria-expanded')==='true'&&!nav.contains(event.target)&&!menu.contains(event.target))setMenuOpen(false);
});
document.addEventListener('keydown',event=>{
 if(menu.getAttribute('aria-expanded')!=='true')return;
 if(event.key==='Escape'){event.preventDefault();setMenuOpen(false,true);}
 if(event.key==='Tab'){
  if(!event.shiftKey&&document.activeElement===menu){event.preventDefault();menuLinks[0].focus();}
  else if(event.shiftKey&&document.activeElement===menuLinks[0]){event.preventDefault();menu.focus();}
  else if(!event.shiftKey&&document.activeElement===menuLinks[menuLinks.length-1]){event.preventDefault();menu.focus();}
 }
});
document.querySelector('.header').addEventListener('focusout',event=>{
 if(menu.getAttribute('aria-expanded')==='true'&&event.relatedTarget&&!document.querySelector('.header').contains(event.relatedTarget))setMenuOpen(false);
});
compactNavigation.addEventListener('change',()=>setMenuOpen(false));
setMenuOpen(false);
const prices=[3.2,2.9,2.6,2.4,2.5,2.8,3.4,4.3,5.1,5.4,5.2,4.6,4.1,3.9,4.4,5.3,6.7,7.6,8.2,8,7.4,6.2,4.8,3.8],chart=document.getElementById('price-chart');
function kind(h){return h<6?'charge':h>=17&&h<=21?'discharge':'hold'}prices.forEach((price,h)=>{const b=document.createElement('button');b.style.height=(price/9*100)+'%';b.dataset.kind=kind(h);b.title=`${String(h).padStart(2,'0')}:00 — ${formatDemoNumber(price)} ₴/kWh`;b.setAttribute('aria-label',b.title);b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>setHour(h));chart.appendChild(b)});
function setHour(h){if(typeof stopDayPlayback==='function'&&!dayPlaybackTick)stopDayPlayback();const time=String(h).padStart(2,'0')+':00';document.getElementById('hour').value=h;document.getElementById('hour-label').textContent=time;document.getElementById('selected-hour').textContent=time;document.getElementById('decision-price').textContent=formatDemoNumber(prices[h])+' ₴';const k=kind(h);document.getElementById('decision-title').textContent=k==='charge'?"Caricare a un prezzo inferiore":k==='discharge'?"Sostituire gli acquisti costosi":h>=22?"Conservare la riserva":"Mantenere la flessibilità";document.getElementById('decision-text').textContent=k==='charge'?"In questo esempio il prezzo notturno è inferiore. Il piano prevede la carica se la differenza di prezzo attesa copre perdite e usura della batteria.":k==='discharge'?"L’energia accumulata copre parte della domanda nelle ore costose. La scarica è limitata dalla potenza e dalla riserva concordata.":h>=22?"In questo esempio il periodo di scarica è terminato. L’accumulo mantiene la riserva concordata fino al prossimo ciclo di pianificazione.":"Nello scenario diurno la priorità è l’autoconsumo della generazione fotovoltaica. L’eccedenza può caricare l’accumulo se il suo stato lo consente.";[...chart.children].forEach((b,i)=>b.setAttribute('aria-pressed',String(i===h)));document.dispatchEvent(new CustomEvent('operion:hour',{detail:{hour:h,kind:k}}))}document.getElementById('hour').addEventListener('input',e=>setHour(Number(e.target.value)));setHour(18);
document.getElementById('year').textContent=new Date().getFullYear();

// Product demonstration. Explicit scenarios, no live telemetry or equipment commands.
const demoPhases=[{time:"02:00 / NOTTE",solar:0,load:110,grid:190,soc:38,battery:"Carica: 80 kW",badge:"SPOSTAMENTO DEGLI ACQUISTI",action:"Accumulare energia per le ore più costose.",reason:"Nel piano dimostrativo la rete copre 110 kW di domanda e 80 kW di carica. La convenienza dipende dalla tariffa, dalle perdite e dall’usura della batteria.",balance:"Bilancio: 190 = 110 + 80 kW",description:"La rete fornisce 190 kW: l’azienda ne consuma 110 e 80 caricano la batteria.",solarActive:false,gridActive:true,reverse:false},{time:"12:00 / GIORNO",solar:240,load:180,grid:0,soc:62,battery:"Carica: 60 kW",badge:"GENERAZIONE PROPRIA",action:"Sfruttare il sole. Accumulare l’eccedenza.",reason:"La generazione supera la domanda attuale. In questo scenario il sito utilizza 180 kW e 60 caricano il BESS.",balance:"Bilancio: 240 = 180 + 60 kW",description:"Il fotovoltaico genera 240 kW: l’azienda ne consuma 180 e 60 caricano la batteria. Acquisto dalla rete: 0 kW.",solarActive:true,gridActive:false,reverse:false},{time:"18:00 / PICCO",solar:35,load:180,grid:0,soc:74,battery:"Scarica: 145 kW",badge:"SOSTITUZIONE DEGLI ACQUISTI COSTOSI",action:"Coprire la domanda con l’energia del BESS.",reason:"35 kW dal fotovoltaico e 145 kW dall’accumulo coprono 180 kW di consumo. La scarica è limitata dalla riserva e dalla potenza concordate.",balance:"Bilancio: 35 + 145 = 180 kW",description:"Il fotovoltaico fornisce 35 kW, la batteria eroga 145 kW e l’azienda consuma 180 kW. Acquisto dalla rete: 0 kW.",solarActive:true,gridActive:false,reverse:true}];
const phaseButtons=[...document.querySelectorAll('[data-phase]')];let demoPhase=1,demoTimer=null;const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
function showDemoPhase(i){demoPhase=i;const p=demoPhases[i];for(const key of ['solar','load','grid','soc'])document.getElementById('demo-'+key).textContent=p[key];for(const key of ['solar','load','grid'])document.getElementById('node-'+key).textContent=p[key]+" kW";document.getElementById('node-battery').textContent=p.battery;for(const key of ['time','badge','action','reason','balance'])document.getElementById('demo-'+key).textContent=p[key];document.getElementById('flow-desc').textContent=p.description;document.getElementById('demo-soc-bar').style.width=p.soc+'%';document.getElementById('path-solar').classList.toggle('flow-inactive',!p.solarActive);document.getElementById('path-grid').classList.toggle('flow-inactive',!p.gridActive);document.getElementById('path-battery').classList.toggle('flow-reverse',p.reverse);phaseButtons.forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));document.dispatchEvent(new CustomEvent('operion:phase',{detail:{phase:i}}));}
const demoPlay=document.getElementById('demo-play');function stopDemo(){if(demoTimer)clearInterval(demoTimer);demoTimer=null;demoPlay.setAttribute('aria-pressed','false');demoPlay.setAttribute('aria-label',"Avvia il cambio automatico degli scenari");demoPlay.textContent="▶ Riproduzione automatica"}function startDemo(){if(demoTimer)return;demoPlay.setAttribute('aria-pressed','true');demoPlay.setAttribute('aria-label',"Metti in pausa il cambio automatico degli scenari");demoPlay.textContent="Ⅱ Pausa";demoTimer=setInterval(()=>showDemoPhase((demoPhase+1)%3),6500)}phaseButtons.forEach((b,i)=>b.addEventListener('click',()=>{stopDemo();showDemoPhase(i)}));demoPlay.addEventListener('click',()=>demoTimer?stopDemo():startDemo());document.addEventListener('visibilitychange',()=>{if(document.hidden)stopDemo()});reducedMotion.addEventListener('change',e=>{if(e.matches)stopDemo()});showDemoPhase(1);
const businessTypes=[{category:"IMPRESE INDUSTRIALI",title:"L’energia deve seguire il ritmo della produzione.",problem:"Turni, reparti diversi e generazione propria creano un profilo di consumo complesso. La programmazione manuale dell’accumulo non coincide sempre con la domanda reale.",person:"Energy manager · direttore tecnico · responsabile finanziario",value:"Una visione unica di alimentazioni, generazione e asset. Un piano operativo del BESS che considera profilo produttivo, tariffa e riserva concordata.",scenario:"Utilizzo del fotovoltaico in autoconsumo e spostamento di parte degli acquisti tra le ore, senza interferire con il processo produttivo.",data:"Profilo di consumo orario, turni, potenza FV/BESS, limiti di connessione e interfacce disponibili."},{category:"LOGISTICA E CATENA DEL FREDDO",title:"Il freddo non aspetta. Riserva e costi vanno coordinati.",problem:"Magazzini e complessi frigoriferi hanno una domanda prolungata. Il funzionamento economico dell’accumulo deve considerare consumi critici e riserva di autonomia.",person:"Responsabile del sito · energy manager · team operativo",value:"Monitoraggio dei carichi frigoriferi e del bilancio complessivo. Stato del BESS trasparente e scenario di utilizzo con un vincolo separato per la riserva.",scenario:"Il fotovoltaico copre la domanda diurna, il BESS sposta parte degli acquisti nelle ore più convenienti. L’autonomia viene valutata separatamente, non garantita a priori.",data:"Domanda critica, durata di autonomia richiesta, potenza dell’inverter, capacità della batteria e funzionamento reale."},{category:"AGRICOLTURA E TRASFORMAZIONE",title:"La domanda stagionale richiede un piano flessibile.",problem:"Durante la stagione cambiano i consumi di un silo o di un impianto di trasformazione. Impostazioni identiche per tutto l’anno possono non corrispondere al funzionamento reale.",person:"Titolare dell’azienda · responsabile tecnico · energy manager",value:"Storico dei consumi per periodo, confronto con la generazione e pianificazione degli asset energetici in base al profilo stagionale.",scenario:"Energia solare propria per i processi diurni, carica del BESS nei periodi concordati e scarica in base alle esigenze del sito. Le linee produttive non vengono commutate senza un progetto specifico.",data:"Programmi stagionali, funzionamento degli impianti principali, fonti di generazione, tariffa e possibilità di misura."},{category:"COMMERCIO E CENTRI COMMERCIALI",title:"Coordina la generazione diurna con i consumi serali.",problem:"Generazione solare, refrigerazione, illuminazione e attività serale creano profili di domanda diversi. Spesso i dati rimangono in sistemi separati.",person:"Direttore del sito · energy manager della rete · responsabile finanziario",value:"Bilancio energetico, confronto dei periodi e piano di utilizzo del BESS. La direzione vede la struttura dei costi, gli ingegneri le condizioni e i limiti dello scenario.",scenario:"Autoconsumo della generazione propria e sostituzione di parte degli acquisti serali più costosi, se tariffa e domanda lo rendono economicamente conveniente.",data:"Orari di attività, domanda diurna e serale, schema di misura, tariffa, fotovoltaico e accumulo esistenti."},{category:"IMMOBILI COMMERCIALI",title:"Trasforma letture disperse nel bilancio dell’edificio.",problem:"Più alimentazioni, aree comuni e orari diversi degli utenti complicano il monitoraggio energetico di uffici, hotel e complessi.",person:"Società di gestione · team operativo · proprietà dell’immobile",value:"Monitoraggio energetico nei punti concordati, storico di generazione e consumo e confronto dei periodi. Se sono presenti asset controllabili, è disponibile un modulo separato di ottimizzazione.",scenario:"Iniziare dalla raccolta dei dati e dal controllo degli scostamenti. Dopo aver valutato il profilo, aggiungere un piano concordato per fotovoltaico e BESS.",data:"Schema delle alimentazioni, elenco dei contatori, carichi comuni e interfacce. Il monitoraggio energetico interno non sostituisce la fatturazione agli inquilini."},{category:"GRUPPI DI SITI",title:"Un criterio comune di valutazione. Regole specifiche per ogni sito.",problem:"App separate, inverter diversi e tariffe differenti rendono più difficile confrontare i siti e individuare le cause degli scostamenti.",person:"Energy manager del gruppo · direttore tecnico · responsabile della rete",value:"Un approccio coerente alla raccolta delle misure, all’analisi dei periodi e alla definizione degli scenari. L’ambito del consolidamento e delle integrazioni viene fissato nel progetto.",scenario:"Un progetto pilota su un sito, con verifica dei dati e dell’effetto. Poi l’estensione della soluzione concordata, considerando le specificità di ogni sede.",data:"Elenco dei siti, modelli dei dispositivi, accessi, qualità dei dati e tariffe. La possibilità di controllo centralizzato viene verificata separatamente."}];
const businessButtons=[...document.querySelectorAll('[data-business]')];function selectBusiness(i,focus=false){businessButtons.forEach((b,j)=>{b.setAttribute('aria-selected',String(j===i));b.tabIndex=j===i?0:-1});const b=businessTypes[i];for(const k of ['category','title','problem','person','value','scenario','data'])document.getElementById('business-'+k).textContent=b[k];const panel=document.getElementById('business-panel');panel.setAttribute('aria-labelledby','business-tab-'+i);panel.classList.remove('content-enter');void panel.offsetWidth;panel.classList.add('content-enter');if(focus)businessButtons[i].focus()}
businessButtons.forEach((b,i)=>{b.addEventListener('click',()=>selectBusiness(i));b.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();selectBusiness(e.key==='Home'?0:e.key==='End'?5:(i+(e.key==='ArrowRight'?1:5))%6,true)}})});selectBusiness(0);
// Progressive scroll reveals: content stays available when motion is reduced or observers are unsupported.
if(!reducedMotion.matches&&'IntersectionObserver' in window){const sections=[...document.querySelectorAll('.module-grid article,.steps article,.software-deliverables p')];sections.forEach(el=>el.classList.add('reveal-item'));document.documentElement.classList.add('has-reveal');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target)}}),{threshold:.08});sections.forEach(el=>observer.observe(el));}
